def test_lineartimecode():
    global ltc_words
    global ltc_samples
    ltc_samples = [
        [sample * 0.75 for sample in word]
        for word in ltc_samples
    ]
    ltc_config = {"sample_rate": 48000, "fps": 50, "device": None}
    generator = ltc.LTCGenerator(ltc_config, None)
    for i in range(len(ltc_words)):
        word, _ = generator.create_next_bitword()
        assert word == ltc_words[i]
        samples = generator.sample_word(word)
        assert len(samples) == len(ltc_samples[i])
        assert samples == ltc_samples[i]
    